var metricsAggregator = require("./metricsAggregator");
class eventLoopMetricsAggregator extends metricsAggregator {
  constructor() {
    super();
  }

  addToExistingMetricData(stats) {
    super.addToExistingMetricData(stats);
    this.sum += stats.sum;
    this.max = stats.max > this.max ? stats.max : this.max;
    this.min = stats.min < this.min ? stats.min : this.min;
  }
}
module.exports = eventLoopMetricsAggregator;
